38	class RoomScreen extends StatefulWidget {
39	  const RoomScreen({
40	    super.key,
41	    required this.server,
42	    required this.room,
43	    required this.token,
44	    required this.name,
45	    this.clientId,
46	    this.initialCopy,
47	    this.pickCopy = pickLocalCopy,
48	    this.pickJellyfin,
49	  });
50	
51	  final Uri server;
52	  final String room;
53	  final String token;
54	  final String name;
55	  final String? clientId;
56	
57	  /// The copy chosen on Home or in the room-ready dialog; opened on entry.
58	  final LocalCopy? initialCopy;
59	  final PickCopy pickCopy;
60	
61	  /// Opens the Jellyfin picker; null when the app has no Jellyfin support in this context.
62	  final PickCopy? pickJellyfin;
63	
64	  @override
65	  State<RoomScreen> createState() => _RoomScreenState();
66	}
67	
68	class _RoomScreenState extends State<RoomScreen> {
69	  late RoomClient _client;
70	  final SyncPlayer _player = SyncPlayer();
71	  late final Timer _pollTimer;
72	  late final Timer _reportTimer;
73	  final List<Member> _members = [];
74	  List<QueueItem> _queue = [];
75	  RoomMeta? _meta;
76	  int _rev = 0;
77	  Playback? _anchor;
78	  bool _clockWasReady = false;
79	  bool _opening = false;
80	  bool _muted = false;
81	  double _volume = _sessionVolume;
82	  bool _fullscreen = false;
83	
84	  _Attempt? _attempt;
85	
86	  /// Opening threw (hashing, a missing file); shown instead of the stage.
87	  String? _openError;
88	
89	  /// The last error the player logged for the open copy; fatal only while nothing loaded.
90	  String? _playerError;
91	  final List<StreamSubscription<Object>> _subs = [];
92	
93	  /// Reconnect bookkeeping: RoomClient is one socket, so a drop means a fresh client.
94	  bool _joinedOnce = false;
95	  int _retries = 0;
96	  Timer? _retryTimer;
97	  String? _gaveUp;
98	
99	  PauseNotice? _pause;
100	  int _pauseSerial = 0;
101	  DateTime? _pauseSentAt;
102	
103	  /// Names and durations of files we hashed here, so queue rows read as titles.
104	  final Map<String, ({String name, int? durationMs})> _known = {};
105	
106	  bool get _joined => _client.status == ConnectionStatus.joined;
107	
108	  @override
109	  void initState() {
110	    super.initState();
111	    _client = _connect(widget.clientId);
112	    _pollTimer = Timer.periodic(pollEvery, (_) => _poll());
113	    _reportTimer = Timer.periodic(reportEvery, (_) => _report());
114	    final stream = _player.player.stream;
115	    void refresh(Object _) {
116	      if (mounted) setState(() {});
117	    }
118	
119	    _subs.addAll([
120	      stream.error.listen((e) {
121	        if (mounted) setState(() => _playerError = e);
122	      }),
123	      stream.buffering.listen(refresh),
124	      stream.completed.listen(refresh),
125	      stream.tracks.listen(refresh),
126	    ]);
127	    _player.player.setVolume(_volume);
128	    final initial = widget.initialCopy;
129	    if (initial != null) {
130	      initial.isRemote ? _openRemote(initial) : _openPath(initial.path);
131	    }
132	  }
133	
134	  @override
135	  void dispose() {
136	    _pollTimer.cancel();
137	    _reportTimer.cancel();
138	    _retryTimer?.cancel();
139	    for (final s in _subs) {
140	      s.cancel();
141	    }
142	    _client.close();
143	    _player.dispose();
144	    if (_fullscreen) defaultExitNativeFullscreen();
145	    super.dispose();
146	  }
147	
148	  RoomClient _connect(String? clientId) => RoomClient(
149	    server: widget.server,
150	    room: widget.room,
151	    token: widget.token,
152	    name: widget.name,
153	    clientId: clientId,
154	    onMessage: _onMessage,
155	    onChange: _onClientChange,
156	  )..connect();
157	
158	  void _onClientChange() {
159	    // The first completed clock burst makes anchors meaningful: apply the one we hold.
160	    if (_client.clock.ready && !_clockWasReady) {
161	      _clockWasReady = true;
162	      _apply();
163	    }
164	    if (_joined) {
165	      _joinedOnce = true;
166	      _retries = 0;
167	    }
168	    if (_client.status == ConnectionStatus.closed) _scheduleReconnect();
169	    setState(() {});
170	  }
171	
172	  /// Retries with backoff, keeping our client id; a refused token or a gone room is final.
173	  void _scheduleReconnect() {
174	    if (_retryTimer?.isActive ?? false) return;
175	    final reason = _client.closeReason ?? 'connection closed';
176	    if (reason.contains('4001') || reason.contains('4004')) {
177	      _gaveUp = reason;
178	      return;
179	    }
180	    final delay = Duration(seconds: math.min(10, 1 << math.min(_retries, 4)));
181	    _retries++;
182	    _retryTimer = Timer(delay, () {
183	      if (!mounted) return;
184	      final id = _client.clientId;
185	      _client.close();
186	      setState(() {
187	        _clockWasReady = false;
188	        _client = _connect(id);
189	      });
190	    });
191	  }
192	
193	  void _onMessage(Message message) {
194	    switch (message.body) {
195	      case WelcomeMsg(:final snapshot):
196	        setState(() {
197	          _rev = snapshot.rev;
198	          _setAnchor(snapshot.playback);
199	          _queue = snapshot.queue;
200	          _learnTitles();
201	          _meta = snapshot.meta ?? _meta;
202	          _members
203	            ..clear()
204	            ..addAll(snapshot.presence);
205	        });
206	        _apply();
207	      case StateMsg state when state.rev > _rev:
208	        setState(() {
209	          _rev = state.rev;
210	          _setAnchor(state.playback);
211	          _queue = state.queue;
212	          _learnTitles();
213	          _meta = state.meta ?? _meta;
214	        });
215	        _apply();
216	      case PresenceMsg p:
217	        setState(() {
218	          _members.removeWhere((m) => m.userId == p.userId);
219	          if (p.joined) _members.add(Member(userId: p.userId, name: p.name));
220	        });
221	      case RejectMsg(:final message):
222	        ScaffoldMessenger.of(
223	          context,
224	        ).showSnackBar(SnackBar(content: Text(message)));
225	      default:
226	        break;
227	    }
228	  }
229	
230	  /// Queue rows carry the title they were added with; keep it so the item stays named once it
231	  /// leaves the queue and plays (the waiting card names the room's file).
232	  void _learnTitles() {
233	    for (final q in _queue) {
234	      final title = q.title;
235	      if (title != null) {
236	        _known.putIfAbsent(
237	          q.itemRef,
238	          () => (name: title, durationMs: q.durationMs),
239	        );
240	      }
241	    }
242	  }
243	
244	  /// Raises a pause notice on a playing → paused transition; clears it once playback resumes.
245	  void _setAnchor(Playback? next) {
246	    final prev = _anchor;
247	    _anchor = next;
248	    if (next == null || !next.paused) {
249	      _pause = null;
250	      return;
251	    }
252	    if (prev == null || prev.paused) return;
253	    final sent = _pauseSentAt;
254	    final others = _members.where((m) => m.userId != _client.clientId).toList();
255	    final String? by;
256	    if (sent != null && DateTime.now().difference(sent) < ownPauseWindow) {
257	      by = 'You';
258	    } else if (others.length == 1) {
259	      by = others.single.name ?? 'Someone';
260	    } else {
261	      by = null;
262	    }
263	    _pause = PauseNotice(
264	      serial: ++_pauseSerial,
265	      positionMs: next.positionMs,
266	      by: by,
267	    );
268	  }
269	
270	  Future<void> _apply() async {
271	    if (!_client.clock.ready) return;
272	    await _player.apply(_anchor, _client.clock.serverNow());
273	    if (mounted) setState(() {});
274	  }
275	
276	  Future<void> _poll() async {
277	    if (!_client.clock.ready) return;
278	    await _player.poll(_anchor, _client.clock.serverNow());
279	    if (mounted) setState(() {});
280	  }
281	
282	  void _report() {
283	    if (_joined && _client.clock.ready) {
284	      _client.sendReport(_player.driftMs ?? 0);
285	    }
286	  }
