288	  Future<void> _openFile() async {
289	    final file = await openFile();
290	    if (file == null || !mounted) return;
291	    await _openPath(file.path);
292	  }
293	
294	  Future<void> _openPath(String path) => _open(
295	    () => _player.open(path),
296	    name: baseName(path),
297	    source: MediaSource.local,
298	  );
299	
300	  /// A remote copy streams as-is under the ref it was picked with; nothing is hashed.
301	  Future<void> _openRemote(LocalCopy copy) => _open(
302	    () => _player.openSource(uri: copy.path, itemRef: copy.itemRef),
303	    name: copy.name,
304	    source: _sourceOf(copy.itemRef),
305	    durationMs: copy.duration?.inMilliseconds,
306	  );
307	
308	  Future<void> _open(
309	    Future<void> Function() open, {
310	    required String name,
311	    required MediaSource source,
312	    int? durationMs,
313	  }) async {
314	    final attempt = (
315	      name: name,
316	      source: source,
317	      open: () => _open(open, name: name, source: source, durationMs: durationMs),
318	    );
319	    setState(() {
320	      _attempt = attempt;
321	      _opening = true;
322	      _openError = null;
323	      _playerError = null;
324	    });
325	    try {
326	      await open();
327	      final ref = _player.itemRef;
328	      if (ref != null) _known[ref] = (name: name, durationMs: durationMs);
329	    } on Object catch (e) {
330	      // Never the raw text: a stream URL carries the viewer's token.
331	      if (mounted) setState(() => _openError = playerErrorReason('$e'));
332	    } finally {
333	      if (mounted) setState(() => _opening = false);
334	    }
335	    await _apply();
336	  }
337	
338	  /// Why our copy can't play, for the error card. A player error only counts while nothing
339	  /// has loaded: decoders also log recoverable errors mid-file.
340	  String? get _error {
341	    if (_openError case final e?) return e;
342	    final logged = _playerError;
343	    if (logged == null || _player.itemRef == null) return null;
344	    return _player.player.state.duration == Duration.zero
345	        ? playerErrorReason(logged)
346	        : null;
347	  }
348	
349	  /// Same path as a local file once the picker hands back a remote copy.
350	  Future<void> _openJellyfin() async {
351	    final pick = widget.pickJellyfin;
352	    if (pick == null) return;
353	    final copy = await pick();
354	    if (copy == null || !mounted) return;
355	    await _openRemote(copy);
356	  }
