358	  Future<void> _addToQueue() async {
359	    final copy = await widget.pickCopy();
360	    if (copy == null || !mounted) return;
361	    _known[copy.itemRef] = (
362	      name: copy.name,
363	      durationMs: copy.duration?.inMilliseconds,
364	    );
365	    _client.sendIntent('queue_add', {'item_ref': copy.itemRef});
366	  }
367	
368	  void _play() {
369	    final ref = _player.itemRef;
370	    _client.sendIntent('play', {'item_ref': ?ref});
371	  }
372	
373	  void _pauseRoom() {
374	    _pauseSentAt = DateTime.now();
375	    _client.sendIntent('pause');
376	  }
377	
378	  int get _roomPositionMs {
379	    final anchor = _anchor;
380	    return anchor == null
381	        ? _player.positionMs
382	        : positionAt(anchor, _client.clock.serverNow());
383	  }
384	
385	  void _seekBy(int deltaMs) => _seekTo(_roomPositionMs + deltaMs);
386	
387	  void _seekTo(int ms) =>
388	      _client.sendIntent('seek', {'position_ms': math.max(0, ms)});
389	
390	  /// The room's item again from the start, for everyone.
391	  void _replay() {
392	    final ref = _anchor?.itemRef ?? _player.itemRef;
393	    _client.sendIntent('play', {'item_ref': ?ref, 'position_ms': 0});
394	  }
395	
396	  /// The head of the queue becomes the room's item.
397	  void _playNext() => _client.sendIntent('skip');
398	
399	  void _toggleMute() {
400	    setState(() => _muted = !_muted);
401	    _player.player.setVolume(_muted ? 0 : _volume);
402	  }
403	
404	  void _setVolume(double level) {
405	    setState(() {
406	      _volume = _sessionVolume = level;
407	      _muted = false;
408	    });
409	    _player.player.setVolume(level);
410	  }
411	
412	  void _setAudioTrack(String id) {
413	    for (final t in _player.player.state.tracks.audio) {
414	      if (t.id == id) _player.player.setAudioTrack(t);
415	    }
416	  }
417	
418	  void _setSubtitleTrack(String id) {
419	    for (final t in _player.player.state.tracks.subtitle) {
420	      if (t.id == id) _player.player.setSubtitleTrack(t);
421	    }
422	  }
423	
424	  /// Audio tracks as the player lists them, minus its `auto` and `no` pseudo-tracks.
425	  List<TrackOption> get _audioTracks {
426	    final state = _player.player.state;
427	    return [
428	      for (final t in state.tracks.audio)
429	        if (t.id != 'auto' && t.id != 'no')
430	          (
431	            id: t.id,
432	            label: _trackLabel(t.id, t.title, t.language),
433	            active: t.id == state.track.audio.id,
434	          ),
435	    ];
436	  }
437	
438	  /// `Off` first, then the file's subtitles; empty when it has none.
439	  List<TrackOption> get _subtitleTracks {
440	    final state = _player.player.state;
441	    final active = state.track.subtitle.id;
442	    final real = [
443	      for (final t in state.tracks.subtitle)
444	        if (t.id != 'auto' && t.id != 'no')
445	          (
446	            id: t.id,
447	            label: _trackLabel(t.id, t.title, t.language),
448	            active: t.id == active,
449	          ),
450	    ];
451	    if (real.isEmpty) return const [];
452	    return [(id: 'no', label: 'Off', active: active == 'no'), ...real];
453	  }
454	
455	  static String _trackLabel(String id, String? title, String? language) {
456	    final parts = [
457	      if (title != null && title.trim().isNotEmpty) title.trim(),
458	      if (language != null && language.trim().isNotEmpty)
459	        language.trim().toUpperCase(),
460	    ];
461	    return parts.isEmpty ? 'Track $id' : parts.join(' · ');
462	  }
