470	  void _showSettings() {
471	    final drift = _player.driftMs;
472	    showDialog<void>(
473	      context: context,
474	      barrierColor: const Color(0x8C000000),
475	      builder: (context) => _SettingsDialog(
476	        rows: [
477	          ('Server', widget.server.host),
478	          ('Room', widget.room),
479	          (
480	            'Connection',
481	            _joined
482	                ? 'Connected · ${_client.clock.rttMs.round()} ms'
483	                : (_gaveUp ?? 'Reconnecting…'),
484	          ),
485	          ('Drift', drift == null ? '—' : '${drift.round()} ms'),
486	          ('Player', _player.status),
487	        ],
488	      ),
489	    );
490	  }
491	
492	  StageMode get _stage {
493	    final anchor = _anchor;
494	    final mine = _player.itemRef;
495	    if (anchor != null && anchor.itemRef != mine) return StageMode.waiting;
496	    return mine == null ? StageMode.empty : StageMode.video;
497	  }
498	
499	  PersonState get _selfState {
500	    final drift = _player.driftMs;
501	    if (!_joined) return PersonState.reconnecting;
502	    if (_player.itemRef == null || _stage == StageMode.waiting) {
503	      return PersonState.noFile;
504	    }
505	    if (_player.player.state.buffering) return PersonState.buffering;
506	    if (drift != null && drift.abs() >= seekAtMs) return PersonState.drifting;
507	    return PersonState.synced;
508	  }
509	
510	  /// Presence plus ourselves. Peers report drift only to the server, so they read as synced.
511	  List<RoomPerson> get _people {
512	    final me = _client.clientId;
513	    final host = _meta?.hostId;
514	    final people = [
515	      for (final m in _members)
516	        m.userId == me
517	            ? RoomPerson(
518	                id: me,
519	                name: widget.name,
520	                you: true,
521	                host: host == me,
522	                state: _selfState,
523	                driftMs: _player.driftMs ?? 0,
524	              )
525	            : RoomPerson(
526	                id: m.userId,
527	                name: m.name ?? 'Guest',
528	                host: host == m.userId,
529	              ),
530	    ];
531	    if (!people.any((p) => p.you)) {
532	      people.insert(
533	        0,
534	        RoomPerson(
535	          id: me,
536	          name: widget.name,
537	          you: true,
538	          host: host == me,
539	          state: _selfState,
540	          driftMs: _player.driftMs ?? 0,
541	        ),
542	      );
543	    }
544	    return [...people.where((p) => p.host), ...people.where((p) => !p.host)];
545	  }
546	
547	  QueueRow _row(String ref, {String? title, int? durationMs}) {
548	    final known = _known[ref];
549	    final parts = ref.split(':');
550	    final duration =
551	        durationMs ??
552	        known?.durationMs ??
553	        (ref == _player.itemRef
554	            ? _player.player.state.duration.inMilliseconds
555	            : null);
556	    final bytes = parts.length > 2 ? int.tryParse(parts[2]) : null;
557	    return (
558	      title:
559	          title ??
560	          known?.name ??
561	          'File ${parts.length > 3 ? parts[3].substring(0, 6) : ref}',
562	      detail: duration != null && duration > 0
563	          ? fmtTime(duration)
564	          : (bytes == null ? '' : fmtBytes(bytes)),
565	    );
566	  }
567	
568	  String get _title {
569	    final meta = _meta;
570	    if (meta == null) return 'Room';
571	    return meta.hostId == _client.clientId
572	        ? 'Your room'
573	        : "${meta.hostName}'s room";
574	  }
575	
576	  /// Who the room waits on to press play. Anchors carry no author, so this is the pause notice's
577	  /// guess while paused, and the host while nothing has played.
578	  String? get _waitingFor {
579	    final anchor = _anchor;
580	    if (anchor != null) return anchor.paused ? _pause?.by : null;
581	    final meta = _meta;
582	    if (meta == null) return null;
583	    return meta.hostId == _client.clientId ? 'You' : meta.hostName;
584	  }
585	
586	  /// Adjusting while the drift policy nudges or is about to correct a playing copy.
587	  SyncState? get _sync {
588	    final anchor = _anchor;
589	    if (_stage != StageMode.video || anchor == null) return null;
590	    if (anchor.paused) return SyncState.inSync;
591	    return _player.nudging || _player.correction != Correction.none
592	        ? SyncState.adjusting
593	        : SyncState.inSync;
594	  }
595	
596	  RoomViewData get _data {
597	    final state = _player.player.state;
598	    final anchor = _anchor;
599	    final error = _error;
600	    final mine = _player.itemRef;
601	    return RoomViewData(
602	      room: widget.room,
603	      title: _title,
604	      invite: inviteUrl(widget.server, widget.token),
605	      connected: _joined,
606	      connecting: !_joinedOnce,
607	      disconnectReason: _gaveUp,
608	      people: _people,
609	      nowPlaying: anchor == null ? null : _row(anchor.itemRef),
610	      upNext: [
611	        for (final q in _queue)
612	          _row(q.itemRef, title: q.title, durationMs: q.durationMs),
613	      ],
614	      stage: _stage,
615	      mismatch: mine != null,
616	      opening: _opening,
617	      buffering: mine != null && state.buffering,
618	      error: error,
619	      ended: mine != null && state.completed,
620	      waitingFor: _waitingFor,
621	      // Never the remote URL itself: it carries the viewer's token.
622	      fileName: error != null || _opening
623	          ? _attempt?.name
624	          : _known[mine]?.name,
625	      source: error != null || _opening
626	          ? _attempt?.source
627	          : (mine == null ? null : _sourceOf(mine)),
628	      roomSource: anchor == null ? null : _sourceOf(anchor.itemRef),
629	      positionMs: mine == null ? 0 : _roomPositionMs,
630	      durationMs: state.duration.inMilliseconds,
631	      bufferedMs: state.buffer.inMilliseconds,
632	      playing: anchor != null && !anchor.paused,
633	      aspect: (state.width ?? 0) > 0 && (state.height ?? 0) > 0
634	          ? state.width! / state.height!
635	          : 16 / 9,
636	      muted: _muted,
637	      volume: _volume,
638	      rate: anchor?.rate ?? 1,
639	      sync: _sync,
640	      driftMs: _player.driftMs,
641	      audioTracks: _audioTracks,
642	      subtitleTracks: _subtitleTracks,
643	      fullscreen: _fullscreen,
644	      pause: _pause,
645	    );
646	  }
647	
648	  @override
649	  Widget build(BuildContext context) => WtScaffold(
650	    child: RoomView(
651	      data: _data,
652	      video: Video(
653	        controller: _player.video,
654	        controls: NoVideoControls,
655	        fill: _fullscreen ? Colors.black : WtColors.board,
656	        pauseUponEnteringBackgroundMode: false,
657	      ),
658	      onBack: () => Navigator.of(context).pop(),
659	      onOpenFile: _openFile,
660	      onOpenJellyfin: widget.pickJellyfin == null ? null : _openJellyfin,
661	      onPlay: _play,
662	      onPause: _pauseRoom,
663	      onSeekBy: _seekBy,
664	      onSeekTo: _seekTo,
665	      onToggleMute: _toggleMute,
666	      onVolume: _setVolume,
