1	/// The Room screen's presentation: top bar, stage, rail, dock, toast. Fed a [RoomViewData]
2	/// snapshot and callbacks, so it renders without a socket or a native player.
3	library;
4	
5	import 'dart:async';
6	import 'dart:math' as math;
7	
8	import 'package:flutter/material.dart';
9	import 'package:flutter/services.dart';
10	
11	import 'format.dart';
12	import 'player.dart' show seekAtMs;
13	import 'room_controls.dart';
14	import 'theme.dart';
15	import 'widgets/button.dart';
16	import 'widgets/chrome.dart';
17	import 'widgets/identity.dart';
18	
19	/// Stage shape for scope files; everything else gets a 16:9 stage.
20	const double scopeAspect = 2.39;
21	
22	/// 16:9, or 2.39:1 when the file is scope-wide; the picture letterboxes inside, never stretched.
23	double stageAspect(double fileAspect) =>
24	    fileAspect >= (16 / 9 + scopeAspect) / 2 ? scopeAspect : 16 / 9;
25	
26	/// The video stage box, for layout tests.
27	const Key roomStageKey = ValueKey('room-stage');
28	
29	/// The dock, for the fullscreen auto-hide tests.
30	const Key roomDockKey = ValueKey('room-dock');
31	
32	/// Fullscreen chrome (dock, room cluster, cursor) hides after this long without pointer movement
33	/// or a key, playing or paused. The corner pills never hide.
34	const Duration chromeHideAfter = Duration(milliseconds: 2500);
35	
36	/// How long the "Esc to exit · F toggles" hint stays up after entering fullscreen.
37	const Duration fullscreenHintFor = Duration(seconds: 2);
38	
39	/// Fullscreen glass: the room cluster, the hint and the corner pills sit on this, never on a bar.
40	const BoxDecoration _glass = BoxDecoration(
41	  color: Color(0x99140A20),
42	  borderRadius: BorderRadius.all(Radius.circular(WtRadius.pill)),
43	  border: Border.fromBorderSide(BorderSide(color: WtColors.line, width: 1.5)),
44	);
45	
46	enum PersonState { synced, buffering, drifting, noFile, reconnecting }
47	
48	class RoomPerson {
49	  const RoomPerson({
50	    required this.id,
51	    required this.name,
52	    this.you = false,
53	    this.host = false,
54	    this.state = PersonState.synced,
55	    this.driftMs = 0,
56	  });
57	  final String id;
58	  final String name;
59	  final bool you;
60	  final bool host;
61	  final PersonState state;
62	  final double driftMs;
63	
64	  /// Synced, or drifting within the seek threshold (the player is still nudging it in).
65	  bool get ready => switch (state) {
66	    PersonState.synced => true,
67	    PersonState.drifting => driftMs.abs() < seekAtMs,
68	    PersonState.buffering ||
69	    PersonState.noFile ||
70	    PersonState.reconnecting => false,
71	  };
72	
73	  String get status => switch (state) {
74	    PersonState.synced => 'Synced',
75	    PersonState.buffering => 'Buffering',
76	    PersonState.drifting =>
77	      'Drifting ${driftMs < 0 ? '−' : '+'}${(driftMs.abs() / 1000).round()}s',
78	    PersonState.noFile => 'No file',
79	    PersonState.reconnecting => 'Reconnecting',
80	  };
81	}
82	
83	/// The ready pill's tooltip: who is not ready, and why.
84	String readyDetail(List<RoomPerson> people) {
85	  final waiting = people.where((p) => !p.ready).toList();
86	  if (waiting.isEmpty) return 'Everyone has the file and is in sync.';
87	  return [
88	    'Not ready yet',
89	    for (final p in waiting) '${p.name}${p.you ? ' (you)' : ''} · ${p.status}',
90	  ].join('\n');
91	}
92	
93	enum StageMode { empty, waiting, video }
94	
95	/// Where a copy comes from: a file on disk, or a stream from the viewer's Jellyfin.
96	enum MediaSource { local, jellyfin }
97	
98	/// `In sync`, or `Adjusting` while the drift policy is correcting.
99	enum SyncState { inSync, adjusting }
100	
101	typedef QueueRow = ({String title, String detail});
102	
103	/// Shown as a toast, then named on the stage while playback stays paused.
104	class PauseNotice {
105	  const PauseNotice({required this.serial, required this.positionMs, this.by});
106	  final int serial;
107	  final int positionMs;
108	
109	  /// Who paused, when known (`You`, or the only other person).
110	  final String? by;
111	}
112	
113	class RoomViewData {
114	  const RoomViewData({
115	    required this.room,
116	    this.title = 'Room',
117	    this.invite,
118	    this.connected = true,
119	    this.connecting = false,
120	    this.disconnectReason,
121	    this.people = const [],
122	    this.nowPlaying,
123	    this.upNext = const [],
124	    this.stage = StageMode.empty,
125	    this.mismatch = false,
126	    this.opening = false,
127	    this.buffering = false,
128	    this.error,
129	    this.ended = false,
130	    this.waitingFor,
131	    this.fileName,
132	    this.source,
133	    this.roomSource,
134	    this.positionMs = 0,
135	    this.durationMs = 0,
136	    this.bufferedMs = 0,
137	    this.playing = false,
138	    this.aspect = 16 / 9,
139	    this.muted = false,
140	    this.volume = 100,
141	    this.rate = 1,
142	    this.sync,
143	    this.driftMs,
144	    this.audioTracks = const [],
145	    this.subtitleTracks = const [],
146	    this.fullscreen = false,
147	    this.pause,
148	  });
149	  final String room;
150	  final String title;
151	  final String? invite;
152	  final bool connected;
153	
154	  /// Not connected yet for the first time, as opposed to dropped.
155	  final bool connecting;
156	
157	  /// Set when the connection is gone for good (bad token, room ended); otherwise we retry.
158	  final String? disconnectReason;
159	  final List<RoomPerson> people;
160	
161	  /// The room's item; null while nobody has pressed play.
162	  final QueueRow? nowPlaying;
163	  final List<QueueRow> upNext;
164	  final StageMode stage;
165	
166	  /// In [StageMode.waiting]: a file is open but it is not the room's file.
167	  final bool mismatch;
168	
169	  /// Our copy is being hashed or loaded; [fileName] names it.
170	  final bool opening;
171	
172	  /// The player is waiting for data.
173	  final bool buffering;
174	
175	  /// Why our copy failed to open or play, in words for the error card.
176	  final String? error;
177	
178	  /// Our copy reached its end.
179	  final bool ended;
180	
181	  /// Who the room waits on to press play: a name, `You`, or null when nobody can tell.
182	  final String? waitingFor;
183	
184	  /// Our copy's display name (a Jellyfin copy's picked title, never its URL).
185	  final String? fileName;
186	
187	  /// Where our copy comes from; null without one.
188	  final MediaSource? source;
189	
190	  /// Where the room's item comes from, for the right "open that file" action.
191	  final MediaSource? roomSource;
192	  final int positionMs;
193	  final int durationMs;
194	  final int bufferedMs;
195	  final bool playing;
196	  final double aspect;
197	  final bool muted;
198	
199	  /// 0–100, kept while muted.
200	  final double volume;
201	
202	  /// The room's chosen speed. Never the drift engine's nudged rate.
203	  final double rate;
204	  final SyncState? sync;
205	
206	  /// Player minus room, for the sync tooltip.
207	  final double? driftMs;
208	  final List<TrackOption> audioTracks;
209	
210	  /// Includes `Off` when the player reports subtitles.
211	  final List<TrackOption> subtitleTracks;
212	  final bool fullscreen;
213	  final PauseNotice? pause;
214	
215	  int get readyCount => people.where((p) => p.ready).length;
216	}
217	
218	class RoomView extends StatefulWidget {
219	  const RoomView({
220	    super.key,
221	    required this.data,
222	    required this.video,
223	    this.onBack,
224	    this.onOpenFile,
225	    this.onOpenJellyfin,
226	    this.onPlay,
227	    this.onPause,
228	    this.onSeekBy,
229	    this.onSeekTo,
230	    this.onToggleMute,
231	    this.onVolume,
232	    this.onFullscreen,
233	    this.onSettings,
234	    this.onAddToQueue,
235	    this.onRetry,
236	    this.onReplay,
237	    this.onPlayNext,
238	    this.onAudioTrack,
239	    this.onSubtitleTrack,
240	  });
241	  final RoomViewData data;
242	  final Widget video;
243	  final VoidCallback? onBack;
244	  final VoidCallback? onOpenFile;
245	
246	  /// Pick a Jellyfin item instead of a local file; null hides the option.
247	  final VoidCallback? onOpenJellyfin;
248	  final VoidCallback? onPlay;
249	  final VoidCallback? onPause;
250	  final ValueChanged<int>? onSeekBy;
251	  final ValueChanged<int>? onSeekTo;
252	  final VoidCallback? onToggleMute;
253	  final ValueChanged<double>? onVolume;
254	  final VoidCallback? onFullscreen;
255	  final VoidCallback? onSettings;
256	  final VoidCallback? onAddToQueue;
257	
258	  /// Open the copy that failed again.
259	  final VoidCallback? onRetry;
260	
261	  /// Play the room's item from the start.
262	  final VoidCallback? onReplay;
263	
264	  /// Move the room to the head of the queue.
265	  final VoidCallback? onPlayNext;
266	  final ValueChanged<String>? onAudioTrack;
267	  final ValueChanged<String>? onSubtitleTrack;
268	
269	  @override
270	  State<RoomView> createState() => _RoomViewState();
271	}
272	
273	class _RoomViewState extends State<RoomView> {
274	  final _playLink = LayerLink();
275	  bool _toast = false;
276	  Timer? _toastTimer;
277	  bool _copied = false;
278	  Timer? _copyTimer;
279	
280	  /// The rail as an overlay sheet, below [wtCompactWidth].
281	  bool _sheet = false;
282	
283	  /// Fullscreen chrome auto-hide. Only a real pointer arms it, so a window nobody has pointed
284	  /// at (and every widget test) keeps its controls.
285	  bool _idle = false;
286	  bool _pointerSeen = false;
287	  bool _overChrome = false;
288	  Timer? _idleTimer;
289	
290	  /// `Show controls` is on: the fullscreen chrome stays up until it is turned off.
291	  bool _pinned = false;
292	
293	  /// The one-off "Esc to exit · F toggles" hint after entering fullscreen.
294	  bool _hint = false;
295	  Timer? _hintTimer;
296	
297	  RoomViewData get _d => widget.data;
298	  bool get _hasFile => _d.stage == StageMode.video;
299	  bool get _live => _hasFile && _d.connected;
300	  bool get _chromeHidden => _d.fullscreen && _idle;

