/// Audio and subtitle picker. Hidden by the dock when there is nothing to choose.
class TrackMenu extends StatelessWidget {
  const TrackMenu({
    super.key,
    required this.audio,
    required this.subtitles,
    this.onAudio,
    this.onSubtitle,
