import 'dart:async';
import 'dart:io';

import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';

/// Loads the app font so layout tests measure real glyph widths instead of
/// the square test font, which is roughly twice as wide.
Future<void> testExecutable(FutureOr<void> Function() testMain) async {
  TestWidgetsFlutterBinding.ensureInitialized();
  final loader = FontLoader('MPlusRounded');
  for (final weight in ['Regular', 'Medium', 'Bold', 'ExtraBold', 'Black']) {
    final bytes = File(
      'assets/fonts/mplus/MPLUSRounded1c-$weight.ttf',
    ).readAsBytesSync();
    loader.addFont(Future.value(ByteData.sublistView(bytes)));
  }
  await loader.load();
  await testMain();
}
  rate: 1.25,
  sync: SyncState.adjusting,
  driftMs: 180,
  fullscreen: true,
);

void main() {
  // Without the icon font every Icon renders as an empty square.
  setUpAll(() async {
    final loader = FontLoader('MaterialIcons')
      ..addFont(rootBundle.load('fonts/MaterialIcons-Regular.otf'));
    await loader.load();
  });

  for (final idle in [false, true]) {
    final name = idle ? 'fullscreen_1440_idle' : 'fullscreen_1440';
    testWidgets('fullscreen at 1440x900${idle ? ', chrome hidden' : ''}', (
      tester,
    ) async {
      useWindow(tester, const Size(1440, 900));
      await tester.pumpWidget(
        MaterialApp(
          theme: wtTheme(),
          debugShowCheckedModeBanner: false,
          home: WtScaffold(
            child: RoomView(
              data: _fullscreenRoom,
              video: const ColoredBox(color: Color(0xFF120A19)),
              onBack: () {},
              onOpenFile: () {},
              onPlay: () {},
              onPause: () {},
              onSeekBy: (_) {},
              onSeekTo: (_) {},
              onToggleMute: () {},
              onFullscreen: () {},
              onSettings: () {},
              onAddToQueue: () {},
            ),
          ),
        ),
      );
      if (idle) {
        // A mouse arms the idle timer; the fake clock runs it out.
        final mouse = await tester.createGesture(kind: PointerDeviceKind.mouse);
        await mouse.addPointer(location: const Offset(700, 400));
        await mouse.moveTo(const Offset(704, 404));
        await tester.pump();
        await tester.pump(chromeHideAfter);
      }
      // Let the entry hint fade so both shots show the steady state.
      await tester.pump(fullscreenHintFor);
      await tester.pump(const Duration(milliseconds: 500));
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('$name.png'),
      );
    });
  }

  for (final (size, name) in [
    (const Size(1440, 900), '1440'),
    (tiledSize, '856'),
  ]) {
    final label = '${size.width.toInt()}x${size.height.toInt()}';

    testWidgets('home at $label', (tester) async {
      useWindow(tester, size);
      await tester.pumpWidget(
        MaterialApp(
          theme: wtTheme(),
          debugShowCheckedModeBanner: false,
          home: HomeScreen(
            api: FakeRoomApi(),
            pickCopy: () async => null,
            jellyfin: FakeJellyfinApi(),
          ),
        ),
      );
      await tester.pump(const Duration(milliseconds: 300));
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('home_$name.png'),
      );
    });

    testWidgets('room at $label', (tester) async {
      useWindow(tester, size);
      await tester.pumpWidget(
        MaterialApp(
          theme: wtTheme(),
          debugShowCheckedModeBanner: false,
          home: WtScaffold(
            child: RoomView(
              data: _room,
              video: const ColoredBox(color: Color(0xFF120A19)),
              onBack: () {},
              onOpenFile: () {},
