            onPressed: _hasFile ? widget.onFullscreen : null,
          ),
          const SizedBox(width: 8),
          WtIconButton(
            icon: Icons.question_mark_rounded,
            tooltip: 'Keyboard shortcuts (?)',
            onPressed: _showShortcuts,
