          Tooltip(
            message: readyDetail(_d.people),
            child: Semantics(
              liveRegion: true,
              child: WtPill(
                label: readyPillLabel(ready, total),
                tone: allIn ? WtTone.live : WtTone.warn,
                dot: allIn ? WtDotStyle.solid : WtDotStyle.ring,
              ),
