/// `−10s` / `+10s`: quiet, labelled, so the play button stays the one loud control.
class _SkipChip extends StatelessWidget {
  const _SkipChip({
    required this.label,
    required this.tooltip,
    required this.onTap,
  });
  final String label;
  final String tooltip;
