        child: ClipRRect(
          borderRadius: BorderRadius.circular(WtRadius.pill),
          child: Stack(
            children: [
              Padding(
                padding: EdgeInsets.only(left: by == null ? 16 : 6, right: 4),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (by == null)
                      const Icon(
                        Icons.pause_rounded,
                        size: 20,
                        color: WtColors.tx2,
                      )
                    else
                      WtAvatar(id: by, name: by, size: 32, ring: bg),
                    const SizedBox(width: 10),
                    Text.rich(
                      TextSpan(
                        children: [
                          if (by != null)
                            TextSpan(
                              text: '$by ',
                              style: const TextStyle(
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          TextSpan(
                            text: by == null
                                ? 'Paused for everyone · ${fmtTime(notice.positionMs)}'
                                : 'paused for everyone · ${fmtTime(notice.positionMs)}',
                          ),
                        ],
                      ),
                      style: const TextStyle(
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                        color: WtColors.text,
                      ),
                    ),
                    const SizedBox(width: 6),
                    WtTextButton(
                      label: 'Resume',
                      compact: true,
                      onPressed: onResume,
                    ),
                  ],
                ),
              ),
              Positioned(
                left: 0,
                right: 0,
                bottom: 0,
                height: 2,
                child: TweenAnimationBuilder<double>(
                  tween: Tween(begin: 1, end: 0),
                  duration: const Duration(seconds: 4),
                  builder: (context, value, _) => FractionallySizedBox(
                    alignment: Alignment.centerLeft,
                    widthFactor: value,
                    child: const ColoredBox(color: WtColors.pink),
                  ),
                ),
              ),
            ],
