/// Where both `Add` routes end, file or Jellyfin: the picked copy's name and duration are
/// remembered under its ref so the row reads as a title, then that ref is queued as-is.
Future<void> queuePicked(
  PickCopy pick, {
  required Map<String, ({String name, int? durationMs})> known,
  required void Function(String op, Map<String, Object?> args) send,
}) async {
  final copy = await pick();
  if (copy == null) return;
  known[copy.itemRef] = (
    name: copy.name,
    durationMs: copy.duration?.inMilliseconds,
  );
  send('queue_add', {'item_ref': copy.itemRef});
}

