import 'player.dart';

class LocalCopy {
  const LocalCopy({
    required this.path,
    required this.bytes,
    required this.itemRef,
    this.duration,
  }) : title = null,
       isRemote = false;

  /// A copy streamed from the viewer's Jellyfin: [url] is played as-is and never hashed.
  const LocalCopy.remote({
    required String url,
    required this.itemRef,
    required String this.title,
    this.duration,
  }) : path = url,
       bytes = 0,
       isRemote = true;

  /// The file on disk, or the stream URL of a remote copy.
  final String path;
  final int bytes;
  final String itemRef;
  final Duration? duration;
  final bool isRemote;

  /// Display name of a remote copy; a local one shows its file name.
  final String? title;

  String get name => title ?? baseName(path);

