group('queue Add', () {
  const jellyRef = 'jellyfin:jelly.example/$jellyItemId';
  const jellyCopy = LocalCopy.remote(
    url: 'http://jelly.example/Videos/$jellyItemId/stream?api_key=secret',
    itemRef: jellyRef,
    title: 'sample-room',
    duration: Duration(seconds: 20),
  );

  testWidgets('offers this computer and Jellyfin when a picker exists', (
    tester,
  ) async {
    useWindow(tester, desktopSizes.first);
    var files = 0;
    var jellyfin = 0;
    await pumpRoom(
      tester,
      video(),
      onAddToQueue: () => files++,
      onQueueJellyfin: () => jellyfin++,
    );
    expect(find.text('From this computer'), findsNothing);
    await tester.tap(find.text('Add'));
    await tester.pump();
    expect(find.text('From this computer'), findsOneWidget);
    expect(find.text('From Jellyfin'), findsOneWidget);
    await tester.tap(find.text('From Jellyfin'));
    await tester.pump();
    expect((files, jellyfin), (0, 1));
    expect(find.text('From Jellyfin'), findsNothing);
    await tester.tap(find.text('Add'));
    await tester.pump();
    await tester.tap(find.text('From this computer'));
    await tester.pump();
    expect((files, jellyfin), (1, 1));
  });

  testWidgets('offers only this computer without a Jellyfin picker', (
    tester,
  ) async {
    useWindow(tester, desktopSizes.first);
    await pumpRoom(tester, video());
    await tester.tap(find.text('Add'));
    await tester.pump();
    expect(find.text('From this computer'), findsOneWidget);
    expect(find.text('From Jellyfin'), findsNothing);
  });

  testWidgets('a Jellyfin pick is queued and remembered under its own ref', (
    tester,
  ) async {
    useWindow(tester, desktopSizes.first);
    final known = <String, ({String name, int? durationMs})>{};
    final sent = <(String, Map<String, Object?>)>[];
    void send(String op, Map<String, Object?> args) => sent.add((op, args));
    await pumpRoom(
      tester,
      video(),
      onAddToQueue: () =>
          queuePicked(() async => hostCopy, known: known, send: send),
      onQueueJellyfin: () =>
          queuePicked(() async => jellyCopy, known: known, send: send),
    );
    await tester.tap(find.text('Add'));
    await tester.pump();
    await tester.tap(find.text('From Jellyfin'));
    await tester.pump();
    expect(sent, [
      ('queue_add', {'item_ref': jellyRef}),
    ]);
    expect(known[jellyRef], (name: 'sample-room', durationMs: 20000));

    // The file route ends in the same intent.
    await tester.tap(find.text('Add'));
    await tester.pump();
    await tester.tap(find.text('From this computer'));
    await tester.pump();
    expect(sent.last, ('queue_add', {'item_ref': hostRef}));
    expect(known[hostRef], (
      name: 'movie-night_1080p.mkv',
      durationMs: hostCopy.duration!.inMilliseconds,
    ));
  });

  testWidgets('a cancelled pick queues nothing', (tester) async {
    final known = <String, ({String name, int? durationMs})>{};
    final sent = <(String, Map<String, Object?>)>[];
    await queuePicked(
      () async => null,
      known: known,
      send: (op, args) => sent.add((op, args)),
    );
    expect(sent, isEmpty);
    expect(known, isEmpty);
  });

  testWidgets('Add is disabled while disconnected', (tester) async {
    useWindow(tester, desktopSizes.first);
    await pumpRoom(tester, video(connected: false), onQueueJellyfin: () {});
    await tester.tap(find.text('Add'), warnIfMissed: false);
    await tester.pump();
    expect(find.text('From Jellyfin'), findsNothing);
  });

  testWidgets('queue rows carry the Jellyfin or Local file chip', (
    tester,
  ) async {
    useWindow(tester, desktopSizes.first);
    await pumpRoom(tester, video());
    // video(): a local file now playing, a Jellyfin item up next; the dock shows no chip.
    expect(find.text('Local file'), findsOneWidget);
    expect(find.text('Jellyfin'), findsOneWidget);
    expect(tester.takeException(), isNull);
  });
});

